<?php

declare(strict_types=1);
require __DIR__.'/../app/bootstrap.php';
use EventMenu\Core\Database;
use EventMenu\Core\Security;
use EventMenu\Services\TicketService;

$pdo=Database::connection();$eventSlug=trim((string)($_GET['evento']??''));$tenantSlug=trim((string)($_GET['empresa']??''));$error=null;
if($tenantSlug===''){$s=$pdo->prepare('SELECT COUNT(*) FROM events e JOIN tenants t ON t.id=e.tenant_id WHERE e.slug=? AND e.status="published" AND t.status="active"');$s->execute([$eventSlug]);if((int)$s->fetchColumn()!==1){http_response_code(404);exit('Informe a empresa do evento.');}$s=$pdo->prepare('SELECT e.*,t.name tenant_name,t.slug tenant_slug,t.primary_color,t.secondary_color FROM events e JOIN tenants t ON t.id=e.tenant_id WHERE e.slug=? AND e.status="published" AND t.status="active" LIMIT 1');$s->execute([$eventSlug]);}
else{$s=$pdo->prepare('SELECT e.*,t.name tenant_name,t.slug tenant_slug,t.primary_color,t.secondary_color FROM events e JOIN tenants t ON t.id=e.tenant_id WHERE t.slug=? AND e.slug=? AND e.status="published" AND t.status="active" LIMIT 1');$s->execute([$tenantSlug,$eventSlug]);}$event=$s->fetch();if(!$event){http_response_code(404);exit('Evento não encontrado.');}
try{$m=$pdo->prepare('SELECT enabled FROM tenant_modules WHERE tenant_id=? AND module_key="events" LIMIT 1');$m->execute([$event['tenant_id']]);$v=$m->fetchColumn();if($v!==false&&!(bool)$v){http_response_code(404);exit('Eventos indisponíveis.');}}catch(Throwable){}
if($_SERVER['REQUEST_METHOD']==='POST'){if(!Security::validateCsrf($_POST['_csrf']??null))$error='Sessão expirada. Atualize a página.';else try{$reservation=(new TicketService())->reservePublic((int)$event['id'],(int)($_POST['batch_id']??0),(int)($_POST['quantity']??1),['name'=>(string)($_POST['name']??''),'email'=>(string)($_POST['email']??''),'phone'=>(string)($_POST['phone']??'')],trim((string)($_POST['coupon']??''))?:null,trim((string)($_POST['promoter']??''))?:null);header('Location: '.app_url('/pedido.php?t='.rawurlencode($reservation['public_token'])),true,303);exit;}catch(Throwable$e){$error=$e->getMessage();}}
$b=$pdo->prepare('SELECT * FROM ticket_batches WHERE event_id=? AND active=1 ORDER BY id');$b->execute([$event['id']]);$batches=$b->fetchAll();function ev_money(int$c):string{return'R$ '.number_format($c/100,2,',','.');}$primary=preg_match('/^#[0-9a-fA-F]{6}$/',(string)($event['primary_color']??''))?$event['primary_color']:'#6d4aff';$secondary=preg_match('/^#[0-9a-fA-F]{6}$/',(string)($event['secondary_color']??''))?$event['secondary_color']:'#8b5cf6';
?><!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="<?= Security::e($primary) ?>"><title><?= Security::e($event['name']) ?> — EventMenu</title><link rel="stylesheet" href="<?= Security::e(app_url('/assets/app.css')) ?>?v=92legacy4"><style>:root{--event1:<?= Security::e($primary) ?>;--event2:<?= Security::e($secondary) ?>}.event-page{background:#f5f6fb;color:#1e1f27}.event-shell{max-width:1080px;margin:auto;padding:24px 18px 70px}.event-hero{padding:38px;border-radius:28px;background:linear-gradient(135deg,var(--event1),var(--event2));color:white;background-size:cover;background-position:center;box-shadow:0 18px 55px #21195b2a}.event-hero h1{font-size:clamp(34px,7vw,72px);line-height:.95;margin:20px 0}.ticket-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(280px,1fr));gap:16px;margin-top:20px}.ticket-card{background:white!important;color:#222!important;border-color:#e3e4ed!important}.event-page input,.event-page select{background:white;color:#222;border:1px solid #dfe1ea}.event-page .muted{color:#737687}.ticket-price{font-size:1.7rem;font-weight:900;color:var(--event1)}</style></head><body class="event-page"><main class="event-shell"><section class="event-hero"<?php if($event['banner_url']):?> style="background-image:linear-gradient(135deg,<?= Security::e($primary) ?>dd,<?= Security::e($secondary) ?>bb),url('<?= Security::e($event['banner_url']) ?>')"<?php endif;?>><strong>EventMenu Premium</strong><p style="opacity:.85"><?= Security::e($event['tenant_name']) ?></p><h1><?= Security::e($event['name']) ?></h1><p><?= nl2br(Security::e($event['description']??'')) ?></p><p><strong><?= Security::e(date('d/m/Y H:i',strtotime($event['starts_at']))) ?></strong><br><?= Security::e($event['venue']??'') ?><br><?= Security::e($event['address']??'') ?></p></section><?php if($error):?><div class="alert error" style="margin-top:18px"><?= Security::e($error) ?></div><?php endif;?><section style="margin-top:24px"><div class="section-head"><h2>Ingressos</h2><span class="muted">Reserva por 15 minutos</span></div><div class="ticket-grid"><?php foreach($batches as$batch):$available=max(0,(int)$batch['quantity_total']-(int)$batch['quantity_sold']-(int)$batch['quantity_reserved']);$now=time();$open=(!$batch['sales_start']||strtotime($batch['sales_start'])<=$now)&&(!$batch['sales_end']||strtotime($batch['sales_end'])>=$now);?><article class="card ticket-card"><span class="badge"><?= Security::e($batch['name']) ?></span><div class="ticket-price"><?= ev_money((int)$batch['price_cents']) ?></div><p class="muted"><?= $available ?> disponíveis</p><?php if($available>0&&$open):?><form method="post" class="form-grid"><input type="hidden" name="_csrf" value="<?= Security::e(Security::csrfToken()) ?>"><input type="hidden" name="batch_id" value="<?= (int)$batch['id'] ?>"><label>Quantidade<select name="quantity"><?php for($i=1;$i<=min(10,$available);$i++):?><option value="<?= $i ?>"><?= $i ?></option><?php endfor;?></select></label><label>Nome<input name="name" required></label><label>E-mail<input type="email" name="email"></label><label>Telefone<input name="phone"></label><label>Cupom<input name="coupon"></label><label>Promotor<input name="promoter"></label><button class="primary span-2">Reservar e pagar</button></form><?php elseif(!$open):?><span class="badge">Fora do período de venda</span><?php else:?><span class="badge">Esgotado</span><?php endif;?></article><?php endforeach;?><?php if(!$batches):?><article class="card ticket-card"><h2>Vendas ainda não abertas</h2></article><?php endif;?></div></section></main></body></html>